fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (per problem statement): start + sub.len() <= main.len()
    // We implement the intended semantics directly.
    if start > main.len() || sub.len() > main.len() - start {
        return false;
    }

    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty subarray always matches.
    if sub.is_empty() {
        return true;
    }
    // If sub is longer, it cannot fit.
    if sub.len() > main.len() {
        return false;
    }

    // Try all possible starting indices k where sub could fit in main.
    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}